<script setup lang="ts">import{Head,Link,router}from'@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import{Button}from'@/components/ui/button';const p=defineProps<{campaign:any,creatives:any[]}>();const submit=(x:any)=>router.post(`/admin/ad-campaigns/${p.campaign.id}/creatives/${x.id}/submit`);const decide=(x:any,d:string)=>router.post(`/admin/ad-campaigns/${p.campaign.id}/creatives/${x.id}/decision`,{decision:d,rejection_reason:d==='reject'?prompt('Rejection reason')||'Rejected':''});const remove=(x:any)=>confirm('Delete this creative?')&&router.delete(`/admin/ad-campaigns/${p.campaign.id}/creatives/${x.id}`);</script><template><Head title="Advertising Creatives"/><div class="space-y-6 p-6"><div class="flex items-start justify-between gap-4"><PageHeader title="Advertising Creatives" :description="`${campaign.name} · ${campaign.advertiser.name}`"/><div class="flex gap-2"><Link :href="`/admin/ad-campaigns/${campaign.id}`"><Button variant="outline">Campaign</Button></Link><Link :href="`/admin/ad-campaigns/${campaign.id}/creatives/create`"><Button>Add Creative</Button></Link></div></div><div v-if="!creatives.length" class="rounded-xl border border-dashed p-10 text-center text-muted-foreground">No creatives yet. Add the first placement-ready image or video.</div><div class="grid gap-5 md:grid-cols-2 xl:grid-cols-3"><article v-for="x in creatives" :key="x.id" class="overflow-hidden rounded-xl border"><div class="aspect-video bg-muted"><img v-if="x.creative_type==='image'" :src="x.media_url" :alt="x.alt_text||x.name" class="h-full w-full object-contain"/><video v-else :src="x.media_url" controls class="h-full w-full"/></div><div class="space-y-3 p-4"><div class="flex items-start justify-between gap-3"><div><h2 class="font-semibold">{{x.name}}</h2><p class="text-sm text-muted-foreground">{{x.placement?.name||'No placement'}} · {{x.width||'—'}} × {{x.height||'—'}}</p></div><span class="rounded-full border px-2 py-1 text-xs capitalize">{{x.status}}</span></div><p v-if="!x.is_placement_compatible" class="text-sm text-destructive">Dimensions do not match the selected placement.</p><p v-if="x.rejection_reason" class="text-sm text-destructive">{{x.rejection_reason}}</p><div class="flex flex-wrap gap-2"><Link v-if="x.status!=='approved'" :href="`/admin/ad-campaigns/${campaign.id}/creatives/${x.id}/edit`"><Button size="sm" variant="outline">Edit</Button></Link><Button v-if="['draft','rejected'].includes(x.status)" size="sm" @click="submit(x)">Submit</Button><Button v-if="x.status==='submitted'" size="sm" @click="decide(x,'approve')">Approve</Button><Button v-if="x.status==='submitted'" size="sm" variant="destructive" @click="decide(x,'reject')">Reject</Button><Button v-if="x.status!=='approved'" size="sm" variant="ghost" @click="remove(x)">Delete</Button></div></div></article></div></div></template>
